$out=Join-Path $dir 'result.json';[IO.File]::WriteAllText($out,(($report|ConvertTo-Json -Depth 5)+[Environment]::NewLine),[Text.UTF8Encoding]::new($false));Write-Output "REPORT $TaskId $((Get-FileHash -LiteralPath $out -Algorithm SHA256).Hash.ToLowerInvariant()) $out";if($code-ne 0){exit $code}
